CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE IF NOT EXISTS users (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('admin','customer')), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, description text DEFAULT '', category text NOT NULL, kind text NOT NULL CHECK(kind IN ('good','service')), image_url text DEFAULT '', price_cents integer NOT NULL CHECK(price_cents>=0), cost_cents integer NOT NULL DEFAULT 0 CHECK(cost_cents>=0), stock_qty integer NOT NULL DEFAULT 0 CHECK(stock_qty>=0), active boolean NOT NULL DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts (code text PRIMARY KEY, name text NOT NULL, type text NOT NULL CHECK(type IN ('asset','liability','equity','revenue','expense')), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS suppliers (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, email text DEFAULT '');
CREATE TABLE IF NOT EXISTS purchases (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, supplier_id integer REFERENCES suppliers(id), payment_account text NOT NULL CHECK(payment_account IN ('1000','1010','2000')), total_cents integer NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_items (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, purchase_id integer NOT NULL REFERENCES purchases(id), product_id integer NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity>0), unit_cost_cents integer NOT NULL CHECK(unit_cost_cents>=0));
CREATE TABLE IF NOT EXISTS orders (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, customer_id integer NOT NULL REFERENCES users(id), payment_method text NOT NULL CHECK(payment_method IN ('cash','transfer','credit')), status text NOT NULL DEFAULT 'unpaid', total_cents integer NOT NULL, paid_cents integer NOT NULL DEFAULT 0, due_date date, delivery_start date NOT NULL, delivery_end date NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id integer NOT NULL REFERENCES orders(id), product_id integer NOT NULL REFERENCES products(id), product_name text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), unit_price_cents integer NOT NULL, unit_cost_cents integer NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id integer NOT NULL REFERENCES orders(id), account_code text NOT NULL CHECK(account_code IN ('1000','1010')), amount_cents integer NOT NULL CHECK(amount_cents>0), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, description text NOT NULL, category text NOT NULL, account_code text NOT NULL REFERENCES accounts(code), payment_account text NOT NULL CHECK(payment_account IN ('1000','1010','2000')), amount_cents integer NOT NULL CHECK(amount_cents>0), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS incomes (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, description text NOT NULL, category text NOT NULL, account_code text NOT NULL REFERENCES accounts(code), deposit_account text NOT NULL CHECK(deposit_account IN ('1000','1010')), amount_cents integer NOT NULL CHECK(amount_cents>0), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_entries (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, memo text NOT NULL, ref_id integer, ref_type text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_lines (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, entry_id integer NOT NULL REFERENCES journal_entries(id), account_code text NOT NULL REFERENCES accounts(code), debit_cents integer NOT NULL DEFAULT 0, credit_cents integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS delivery_prints (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id integer NOT NULL REFERENCES orders(id), printed_at timestamptz NOT NULL DEFAULT now(), printed_date date NOT NULL, printed_by integer NOT NULL REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id);
CREATE INDEX IF NOT EXISTS idx_orders_created ON orders(created_at);
CREATE INDEX IF NOT EXISTS idx_journal_lines_account ON journal_lines(account_code);
